/// Finds the smallest index k in [lo, hi] such that:
///   - for all r in [lo, k), a[r] < x
///   - for all r in [k, hi), a[r] >= x
/// Equivalently, this is the classic “lower bound” for x in a[lo..hi].
///
/// Precondition: hi <= a.len()
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    let mut low = lo;
    let mut high = hi;
    while low < high {
        // avoid overflow; (low + high) / 2 might overflow if indices are huge,
        // but here hi ≤ 1000 so it’s not a practical concern.
        let mid = low + (high - low) / 2;
        if a[mid] < x {
            // the lower bound must be to the right of mid
            low = mid + 1;
        } else {
            // a[mid] >= x, so mid could still be the lower bound
            high = mid;
        }
    }
    low
}

/// Searches only the first 1000 elements of `a` (assumed sorted non-decreasingly)
/// for the lower bound of `x`.  Returns an index `k` in `0..=1000` such that
///
///   - for every r in 0..k, a[r] < x
///   - for every r in k..1000, a[r] >= x
///
/// If `x` is less than or equal to `a[0]`, this returns 0.  If `x` is greater
/// than all of `a[0..1000]`, this returns 1000.
fn search_1000(a: &[i32], x: i32) -> usize {
    // We know we only care about the prefix [0, 1000).
    search_range_helper(a, x, 0, 1000)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_search_range_helper() {
        // simple sorted slice
        let a = [1, 3, 3, 5, 7, 9];
        // search in [1..5) => [3,3,5,7]
        // lower_bound of 3 is index 1
        assert_eq!(search_range_helper(&a, 3, 1, 5), 1);
        // lower_bound of 4 is index 3
        assert_eq!(search_range_helper(&a, 4, 1, 5), 3);
        // lower_bound of 8 is index 4
        assert_eq!(search_range_helper(&a, 8, 1, 5), 4);
        // lower_bound of 10 in [0..6) is 6
        assert_eq!(search_range_helper(&a, 10, 0, 6), 6);
    }

    #[test]
    fn test_search_1000() {
        // make a 0..999 sorted array
        let mut a = Vec::with_capacity(1200);
        for i in 0..1200 {
            // first 1000 are 0,1,2,...,999
            // rest we don't care
            a.push(i as i32);
        }
        // lower_bound(100) is 100
        assert_eq!(search_1000(&a, 100), 100);
        // lower_bound(0) is 0
        assert_eq!(search_1000(&a, 0), 0);
        // lower_bound(999) is 999
        assert_eq!(search_1000(&a, 999), 999);
        // lower_bound(1000) is 1000 (past all 0..999)
        assert_eq!(search_1000(&a, 1000), 1000);
    }
}